import { useState } from 'react';
import { useLocation, useNavigate, Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { verifyOtp } from '../api';

export default function VerifyOtp() {
  const [otp, setOtp] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const location = useLocation();
  const navigate = useNavigate();

  const email = location.state?.email || '';

  const onSubmit = async (e) => {
    e.preventDefault();
    if (!email) {
      setError('Email is missing. Please signup again.');
      return;
    }
    setError('');
    setLoading(true);
    try {
      await verifyOtp({ email, otp });
      navigate('/login', { state: { message: 'OTP verified. Please login.' } });
    } catch (err) {
      setError(err.response?.data?.error || 'Invalid OTP');
    } finally {
      setLoading(false);
    }
  };

  return (
    <motion.div initial={{ opacity: 0, y: 15 }} animate={{ opacity: 1, y: 0 }} className="max-w-xl mx-auto mt-16 bg-slate-800 rounded-xl shadow-lg p-8">
      <h1 className="text-2xl font-bold mb-4">OTP Verification</h1>
      <p className="text-sm text-slate-300 mb-4">Enter the 6-digit OTP sent to {email}. (Dev: check backend console log)</p>
      <form onSubmit={onSubmit} className="space-y-4">
        <input name="otp" value={otp} onChange={(e) => setOtp(e.target.value)} placeholder="6-digit OTP" className="w-full p-3 rounded-lg bg-slate-700" required />
        {error && <p className="text-red-400">{error}</p>}
        <button type="submit" disabled={loading} className="w-full py-3 bg-emerald-600 hover:bg-emerald-500 rounded-lg font-semibold transition">
          {loading ? 'Verifying...' : 'Verify OTP'}
        </button>
      </form>
      <p className="mt-4 text-sm text-slate-300">Go back to <Link to="/signup" className="text-cyan-300">Signup</Link></p>
    </motion.div>
  );
}
